#include "timer_ccu6.h"

/**********************************************************************************************************************
 * API IMPLEMENTATION
 **********************************************************************************************************************/
/*
 * Returns the version of the TIMER APP.
 */
ACS_APP_VERSION_t TIMER_CCU6_GetAppVersion(void)
{
  ACS_APP_VERSION_t version;

  version.major = TIMER_CCU6_MAJOR_VERSION;
  version.minor = TIMER_CCU6_MINOR_VERSION;
  version.patch = TIMER_CCU6_PATCH_VERSION;

  return version;
}

/*
 * This function initializes a TIMER APP based on user configuration.
 */
TIMER_CCU6_STATUS_t TIMER_CCU6_Init(TIMER_CCU6_t *handle)
{
  TIMER_CCU6_STATUS_t status = TIMER_CCU6_STATUS_SUCCESS;

  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  if (!handle->app_is_initialized)
  {
    if (CCU6_GENERIC_Init(handle->ccu6_generic_handle) == CCU6_GENERIC_STATUS_SUCCESS)
    {
      /* Check for APP instance is initialized or not */
      IfxCcu6_Timer_initModule(&handle->timer_ccu6_handle, handle->app_config->lld_config);
      if (handle->app_config->single_shot_mode == TRUE)
      {
        IfxCcu6_Timer_startSingleShotMode(&handle->timer_ccu6_handle);
      }
      if (handle->app_config->interrupt != NULL_PTR)
      {
        IfxCcu6_enableInterrupt(handle->timer_ccu6_handle.ccu6, handle->app_config->interrupt->source);
        IfxCcu6_routeInterruptNode(handle->timer_ccu6_handle.ccu6, handle->app_config->interrupt->source, handle->app_config->interrupt->service_request);
      }
      if (handle->app_config->start_after_init == TRUE)
      {
        /* Start the timer */
        TIMER_CCU6_Start(handle);
      }
      handle->app_is_initialized = TRUE;
    }
    else
    {
      status = TIMER_CCU6_STATUS_FAILURE;
    }
  }

  return (status);
}

/*
 * This function starts the timer to generate the events for the specified time_interval value
 */
TIMER_CCU6_STATUS_t TIMER_CCU6_Start(TIMER_CCU6_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxCcu6_Timer_start(&handle->timer_ccu6_handle);

  return (TIMER_CCU6_STATUS_SUCCESS);
}

/*
 * This function stops and clears the timer
 */
TIMER_CCU6_STATUS_t TIMER_CCU6_Stop(TIMER_CCU6_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxCcu6_Timer_stop(&handle->timer_ccu6_handle);

  return (TIMER_CCU6_STATUS_SUCCESS);
}

/*
 * This function returns the status of the timer
 */
boolean TIMER_CCU6_GetTimerStatus(TIMER_CCU6_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));
  return IfxCcu6_getTimerRunStatus(handle->timer_ccu6_handle.ccu6, handle->timer_ccu6_handle.timer);
}

/*
 * This function changes the PWM period in us which in turn changes the time tick interval value by checking that
 * the given time tick value is within supported range. New interval is effective after period match
 */
TIMER_CCU6_STATUS_t TIMER_CCU6_SetTimeInterval(TIMER_CCU6_t *handle, float32 time_interval)
{
  TIMER_CCU6_STATUS_t ret = TIMER_CCU6_STATUS_FAILURE;
  uint32 new_period_reg;

  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  /* If specified time interval is applicable */
  if (handle->app_config->period_min <= time_interval && time_interval <= handle->app_config->period_max)
  {
    /* Calculation of new period value */
	new_period_reg = (uint32)(time_interval * (handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12 ? handle->app_config->lld_config->base.t12Frequency : handle->app_config->lld_config->base.t13Frequency) / (1000 * 1000));

    /* Prevent period value becomes 0 */
    if (new_period_reg > 1)
    {
      new_period_reg--;
    }

    /* If calculated period value is applicable */
    if (new_period_reg <= 0xFFFF)
    {
      /* Set new timer interval */
      if (handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12)
      {
        IfxCcu6_setT12PeriodValue(handle->timer_ccu6_handle.ccu6, (uint16)new_period_reg);
        handle->timer_ccu6_handle.base.t12Period = new_period_reg;
      }
      else
      {
        IfxCcu6_setT13PeriodValue(handle->timer_ccu6_handle.ccu6, (uint16)new_period_reg);
        handle->timer_ccu6_handle.base.t13Period = new_period_reg;
      }
      ret = TIMER_CCU6_STATUS_SUCCESS;
    }
  }

  return (ret);
}

/*
 * Get current time interval for the event generation.
 */
TIMER_CCU6_STATUS_t TIMER_CCU6_GetTimeInterval(TIMER_CCU6_t *handle, float32 *time_interval)
{
  TIMER_CCU6_STATUS_t ret = TIMER_CCU6_STATUS_FAILURE;
  uint32 current_period_reg;
  uint32 current_freq;

  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL && timer_interval != NULL));

  /* Get current timer interval */
  if (handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12)
  {
    current_period_reg = handle->timer_ccu6_handle.base.t12Period;
    current_freq       = handle->timer_ccu6_handle.base.t12Frequency;
  }
  else
  {
    current_period_reg = handle->timer_ccu6_handle.base.t13Period;
    current_freq       = handle->timer_ccu6_handle.base.t13Frequency;
  }
  *time_interval = (float32)(current_period_reg + 1) * 1000 * 1000 / current_freq;

  return (ret);
}

/*
 * This function reads the timer event(period match interrupt) status of the given timer
 */
boolean TIMER_CCU6_GetEvent(TIMER_CCU6_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));
  boolean status;

  status = IfxCcu6_getInterruptStatusFlag(handle->timer_ccu6_handle.ccu6,
                                          handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12
                                            ? IfxCcu6_InterruptSource_t12PeriodMatch
                                            : IfxCcu6_InterruptSource_t13PeriodMatch);
  return (status);
}

/*
 * This function clears the period match interrupt status of the given timer.
 */
void TIMER_CCU6_ClearEvent(TIMER_CCU6_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxCcu6_clearInterruptStatusFlag(handle->timer_ccu6_handle.ccu6,
                                   handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12
                                     ? IfxCcu6_InterruptSource_t12PeriodMatch
                                     : IfxCcu6_InterruptSource_t13PeriodMatch);
}

/*
 * This function returns the current time value
 */
float32 TIMER_CCU6_GetTime(TIMER_CCU6_t *handle)
{
  uint32 ltimer_val;

  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  /* get current counter value */
  ltimer_val = (uint32)IfxCcu6_readTimer(handle->timer_ccu6_handle.ccu6, handle->timer_ccu6_handle.timer);

  /* calculate the time value in micro seconds */
  return((float32)(ltimer_val * 1000 * 1000) / (handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12
                                                  ? handle->timer_ccu6_handle.base.t12Frequency
                                                  : handle->timer_ccu6_handle.base.t13Frequency));
}

/*
 * Clear the timer
 */
TIMER_CCU6_STATUS_t TIMER_CCU6_Clear(TIMER_CCU6_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  /* clear counter value */
  IfxCcu6_clearCounter(handle->timer_ccu6_handle.ccu6,
                       handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t12,
                       handle->timer_ccu6_handle.timer == IfxCcu6_TimerId_t13);

  return (TIMER_CCU6_STATUS_SUCCESS);
}

